              child: ExcludeSemantics(
                excluding: widget.semanticLabel != null,
                child: widget.builder(
                  context,
                  PressableState(
                    hovered: _hovered && _enabled,
                    pressed: _pressed,
                    focused: _focused,
                    enabled: _enabled,
                  ),
                ),
              ),
            ),
          ),
        ),
      ),
    );
  }
}
