    final curve = CurvedAnimation(parent: _enter, curve: Curves.easeOut);
    return Semantics(
      liveRegion: true,
      container: true,
      child: MouseRegion(
        onEnter: (_) => _timer?.cancel(),
        onExit: (_) => _start(),
        child: Dismissible(
          key: toast.key,
          direction: DismissDirection.horizontal,
          onDismissed: (_) => widget.onDone(),
          child: still
              ? card
              : FadeTransition(
                  opacity: curve,
                  child: SlideTransition(
                    position: Tween(
                      begin: const Offset(0, .5),
                      end: Offset.zero,
